changeSet.sql:
UPDATE wf.workflow_task
SET assignee_ref = assignment_ref
WHERE status = 'OPEN' AND assignment_kind = 'USER';

ALTER TABLE wf.workflow_task WITH CHECK ADD CONSTRAINT ck_workflow_task_assignee CHECK (
    (assignee_ref IS NULL OR DATALENGTH(assignee_ref) BETWEEN 2 AND 400)
    AND (assignment_kind <> 'USER' OR status <> 'OPEN' OR assignee_ref IS NOT NULL)
    AND (assignment_kind <> 'USER' OR assignee_ref IS NULL OR
        (assignee_ref = assignment_ref AND DATALENGTH(assignee_ref) = DATALENGTH(assignment_ref)))
);
